def parse_duration(s: str) -> int:
    if not s:
        raise ValueError("Input string is empty")

    total_seconds = 0
    current_number = ""
    for char in s:
        if char.isdigit():
            current_number += char
        elif char in "dhms":
            if not current_number:
                raise ValueError("Malformed string: missing number before unit")
            number = int(current_number)
            if char == "d":
                total_seconds += number * 24 * 60 * 60
            elif char == "h":
                total_seconds += number * 60 * 60
            elif char == "m":
                total_seconds += number * 60
            elif char == "s":
                total_seconds += number
            current_number = ""
        else:
            raise ValueError(f"Invalid character '{char}' in input string")

    if current_number:
        raise ValueError("Malformed string: missing unit after number")

    return total_seconds
```

