1. **Tokenize the expression**: Split the expression into tokens (numbers, operators, parentheses).
2. **Parse the expression**: Use recursive functions to parse the expression according to the operator precedence and associativity rules.
3. **Evaluate the expression**: Evaluate the parsed expression to get the result.

Let's implement this step-by-step:

```python
import re

def tokenize(expression):
    # Tokenize the expression using regular expressions
    return re.findall(r'\d+|\+|-|\*|/|\(|\)', expression)

def parse(tokens, index=0):
    # Base case: if we've reached the end of the tokens, return the last token
    if index == len(tokens):
        return None, index

    token = tokens[index]

    # If the token is a number, return it as an integer
    if token.isdigit():
        return int(token), index + 1

    # If the token is a left parenthesis, parse the expression inside the parentheses
    if token == '(':
        result, index = parse(tokens, index + 1)
        # Find the matching right parenthesis
        while index < len(tokens) and tokens[index] != ')':
            index += 1
        return result, index + 1

    # If the token is an operator, parse the next token and apply the operator
    if token in '+-*/':
        left, index = parse(tokens, index)
        right, index = parse(tokens, index)
        if token == '+':
            return left + right, index
        elif token == '-':
            return left - right, index
        elif token == '*':
            return left * right, index
        elif token == '/':
            return int(left / right), index

    # If the token is unexpected, raise an error
    raise ValueError(f"Unexpected token: {token}")

def evaluate(expr: str) -> int:
    # Tokenize the expression
    tokens = tokenize(expr)
    # Parse and evaluate the expression
    result, _ = parse(tokens)
    return result

