import ast

def evaluate(expr: str) -> int:
    class ExpressionEvaluator(ast.NodeVisitor):
        def visit_BinOp(self, node):
            left_value = self.visit(node.left)
            right_value = self.visit(node.right)
            if isinstance(node.op, (ast.Add, ast.Sub)):
                return left_value + right_value if isinstance(node.op, ast.Add) else left_value - right_value
            elif isinstance(node.op, (ast.Mult, ast.Div)):
                result = left_value * right_value if isinstance(node.op, ast.Mult) else int(left_value / right_value)
                return result
            else:
                raise ValueError(f"Unsupported operator {type(node.op).__name__}")

        def visit_Num(self, node):
            return node.n

        def visit_UnaryOp(self, node):
            if isinstance(node.op, ast.USub):
                return -self.visit(node.operand)
            else:
                raise ValueError(f"Unsupported operator {type(node.op).__name__}")

        def visit_UnaryExpr(self, node):
            return self.visit(node.operand)

        def visit_Call(self, node):
            if isinstance(node.func, ast.Name) and node.func.id == 'int':
                return self.visit(node.args[0])
            else:
                raise ValueError(f"Unsupported function call {node.func.id}")

        def visit_NameConstant(self, node):
            return node.value

        def visit_Str(self, node):
            return node.s

        def visit_Name(self, node):
            return node.id

        def generic_visit(self, node):
            raise ValueError(f"Unsupported node type {type(node).__name__}")

        def visit(self, node):
            result = super().visit(node)
            if isinstance(result, ast.AST):
                raise ValueError(f"Node {type(result).__name__} not evaluated")
            return result

    # Parse the expression string into an AST
    tree = ast.parse(expr, mode='eval').body

    # Evaluate the AST
    evaluator = ExpressionEvaluator()
    result = evaluator.visit(tree)

    return result
