def evaluate(expr: str) -> int:
    # Tokenize the expression
    def tokenize(expression):
        tokens, i, n = [], 0, len(expression)
        while i < n:
            if expression[i].isdigit():
                j = i
                while j < n and expression[j].isdigit():
                    j += 1
                tokens.append(int(expression[i:j]))
                i = j
            elif expression[i] in '+-*/':
                tokens.append(expression[i])
                i += 1
            elif expression[i] == '(':
                tokens.append(expression[i])
                i += 1
            elif expression[i] == ')':
                tokens.append(expression[i])
                i += 1
            else:
                i += 1
        return tokens

    # Evaluate an expression with a given operator precedence
    def apply_operator(operands, operators):
        while operators and operators[-1] in ['*', '/']:
            op = operators.pop()
            b = operands.pop()
            a = operands.pop()
            if op == '*':
                operands.append(a * b)
            else:
                operands.append(int(a / b))
        return operands, operators

    # Evaluate the expression using a stack-based approach
    def evaluate_expression(tokens):
        operands, operators = [], []
        i = 0
        while i < len(tokens):
            token = tokens[i]
            if isinstance(token, int):
                operands.append(token)
            elif token in '+-':
                while operators and operators[-1] in '+-':
                    operands, operators = apply_operator(operands, operators)
                operators.append(token)
            elif token in '*/':
                operators.append(token)
            elif token == '(':
                operators.append(token)
            elif token == ')':
                while operators[-1] != '(':
                    operands, operators = apply_operator(operands, operators)
                operators.pop()
            i += 1
        while operators:
            operands, operators = apply_operator(operands, operators)
        return operands[0]

    tokens = tokenize(expr)
    return evaluate_expression(tokens)
