def evaluate(expr: str) -> int:
    def consume_char(c):
        nonlocal index
        if index < len(expr) and expr[index] == c:
            index += 1
        else:
            raise ValueError(f"Expected '{c}' at position {index}")

    def parse_term():
        if expr[index] == '(':
            consume_char('(')
            result = parse_expr()
            consume_char(')')
            return result
        else:
            num = ''
            while index < len(expr) and expr[index].isdigit():
                num += expr[index]
                index += 1
            return int(num)

