def trapped_water(heights: list[int]) -> int:
    if not heights:
        return 0

    left, right = 0, len(heights) - 1
    left_max, right_max = 0, 0
    trapped_water = 0

    while left < right:
        if heights[left] <= heights[right]:
            # Update left_max if the current bar is higher
            if heights[left] >= left_max:
                left_max = heights[left]
            else:
                # Water trapped at this position is the difference between left_max and current bar height
                trapped_water += left_max - heights[left]
            left += 1
        else:
