from collections import deque

def count_islands(grid: list[str]) -> int:
    if not grid or not grid[0]:
        return 0

    rows, cols = len(grid), len(grid[0])
    island_count = 0

    def bfs(r, c):
        q = deque()
        q.append((r, c))
        grid[r] = grid[r][:c] + '0' + grid[r][c+1:]
        while q:
            row, col = q.popleft()
            directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
            for dr, dc in directions:
                nr, nc = row + dr, col + dc
                if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '1':
                    q.append((nr, nc))
                    grid[nr] = grid[nr][:nc] + '0' + grid[nr][nc+1:]

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == '1':
                island_count += 1
                bfs(r, c)

    return island_count
