To solve the problem of finding the number of ways to place n non-attacking queens on an n x n chessboard, we can use a backtracking approach. The idea is to place queens one by one in different columns, starting from the leftmost column. When placing a queen in a column, we check for clashes with already placed queens. In the current column, if we find a row in which there is no clash, we mark this cell and move to the next column. If we do not find such a row due to the presence of multiple queens in the same row, column, or diagonal, we backtrack and return false.

Here is the Python function that implements this approach:

```python
def n_queens(n: int) -> int:
    def is_safe(board: list, row: int, col: int) -> bool:
        # Check this row on left side
        for i in range(col):
            if board[row][i] == 1:
                return False

        # Check upper diagonal on left side
        for i, j in zip(range(row, -1, -1), range(col, -1, -1)):
            if board[i][j] == 1:
                return False

        # Check lower diagonal on left side
        for i, j in zip(range(row, n, 1), range(col, -1, -1)):
            if board[i][j] == 1:
                return False

        return True

    def solve_n_queens(board: list, col: int) -> bool:
        # Base case: If all queens are placed
        if col >= n:
            return True

        # Consider this column and try placing this queen in all rows one by one
        for i in range(n):
            if is_safe(board, i, col):
                # Place this queen in board[i][col]
                board[i][col] = 1

                # recur to place rest of the queens
                if solve_n_queens(board, col + 1):
                    return True

                # If placing queen in board[i][col] doesn't lead to a solution, then remove queen from board[i][col]
                board[i][col] = 0  # BACKTRACK

        # if the queen cannot be placed in any row in this column col then return false
        return False

    # Initialize the board as a list of lists, all elements set to 0
    board = [[0 for _ in range(n)] for _ in range(n)]
    solutions = 0

    # Use solve_n_queens to count the number of solutions
    if solve_n_queens(board, 0):
        solutions += 1

    return solutions

