def paths_with_obstacles(grid: list[list[int]]) -> int:
    m, n = len(grid), len(grid[0])

    # Check if the start or end cell is blocked
    if grid[0][0] == 1 or grid[m-1][n-1] == 1:
        return 0

    # Initialize DP table with zeros
    dp = [[0] * n for _ in range(m)]

    # Set the starting point
    dp[0][0] = 1

    # Initialize first row and column if not blocked
    for i in range(1, m):
        if grid[i][0] == 0:
            dp[i][0] = dp[i-1][0]
        else:
            break

    for j in range(1, n):
        if grid[0][j] == 0:
            dp[0][j] = dp[0][j-1]
        else:
            break

    # Fill the DP table
    for i in range(1, m):
        for j in range(1, n):
            if grid[i][j] == 0:
