def min_coins(coins: list[int], amount: int) -> int:
    # Initialize a table to store the minimum number of coins for each amount
    dp = [float('inf')] * (amount + 1)
    dp[0] = 0  # Base case: 0 coins are needed to make an amount of 0

    # Iterate over each amount from 1 to the target amount
    for i in range(1, amount + 1):
        # For each coin, update the dp table if a smaller number of coins is found
        for coin in coins:
            if coin <= i:
                dp[i] = min(dp[i], dp[i - coin] + 1)

    # Check if the amount can be made with the available coins
    return dp[amount] if dp[amount] != float('inf') else -1
