To solve this problem, we will use a method known as shunting yard algorithm to convert the infix expression to postfix notation (also known as Reverse Polish Notation) and then evaluate the postfix expression. The shunting yard algorithm uses a stack to hold operators and parentheses, and the output is a postfix expression that can be evaluated easily.

Here's a step-by-step guide to implement the `evaluate` function:

1. **Tokenize the expression**: Split the expression into tokens (numbers, operators, parentheses).
2. **Shunting yard algorithm**: Use a stack to manage operators and parentheses, and an output queue to build the postfix expression.
3. **Evaluate the postfix expression**: Use a stack to evaluate the postfix expression by pushing numbers and popping and applying operators as necessary.

Let's implement the function:

```python
def evaluate(expr: str) -> int:
    def precedence(op):
        if op in "+-":
            return 1
        if op in "*/":
            return 2
        return 0

    def apply_operator(operators, values):
        operator = operators.pop()
        right = values.pop()
        left = values.pop()
        if operator == "+":
            values.append(left + right)
        elif operator == "-":
            values.append(left - right)
        elif operator == "*":
            values.append(left * right)
        elif operator == "/":
            values.append(int(left / right))  # Python 3 truncates towards zero

    def evaluate_expression(tokens):
        values = []
        operators = []
        i = 0
        while i < len(tokens):
            token = tokens[i]
            if token.isdigit():
                value = 0
                while i < len(tokens) and tokens[i].isdigit():
                    value = value * 10 + int(tokens[i])
                    i += 1
                values.append(value)
                i -= 1
            elif token == "(":
                operators.append(token)
            elif token == ")":
                while operators and operators[-1] != "(":
                    apply_operator(operators, values)
                operators.pop()  # Remove '('
            else:  # token is an operator
                while (operators and precedence(operators[-1]) >= precedence(token)):
                    apply_operator(operators, values)
                operators.append(token)
            i += 1
        while operators:
            apply_operator(operators, values)
        return values[0]

    # Tokenize the expression
    tokens = []
    i = 0
    while i < len(expr):
        if expr[i].isspace():
            i += 1
        elif expr[i] in "+-*/()":
            tokens.append(expr[i])
            i += 1
        elif expr[i].isdigit():
            value = 0
            while i < len(expr) and expr[i].isdigit():
                value = value * 10 + int(expr[i])
                i += 1
            tokens.append(str(value))
            i -= 1
        else:
            i += 1
    return evaluate_expression(tokens)

